    expect(translate('ru', 'greeting.title', {name: 'Аня'})).toBe('Привет, Аня!');
  });

  it('keeps unknown placeholders untouched', () => {
    expect(translate('en', 'greeting.title', {})).toBe('Hello, {name}!');
  });
