  it('ignores invalid saved values and falls back to navigator languages', () => {
    expect(detectInitialLang(storageWith('xx'), ['de-DE', 'ru-RU'])).toBe('ru');
    expect(detectInitialLang(storageWith(null), ['en-GB'])).toBe('en');
